namespace ghidra.app.plugin.core.clipboard;








using docking;
using docking.widgets.list;
using ghidra.app.util;
using ghidra.util;

public class CopyPasteSpecialDialog : DialogComponentProvider {

	private ListPanel listPanel;
	private JPanel mainPanel;

	private List<object> availableTypes;
	private object selectedType;

	public CopyPasteSpecialDialog(ClipboardPlugin plugin, List<object> availableTypes, string title) : base(title, true)
    {
		this.availableTypes = availableTypes;

		mainPanel = createPanel();
		addWorkPanel(mainPanel);

		addOKButton();
		addCancelButton();

		setHelpLocation(new HelpLocation("ClipboardPlugin", "Copy_Special"));
	}

	private JPanel createPanel() {
		mainPanel = new JPanel(new BorderLayout());

		listPanel = new ListPanel();
		listPanel.setListData(availableTypes.toArray());
		JList list = listPanel.getList();
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setVisibleRowCount(Math.max(3, Math.min(availableTypes.size(), 7)));
		list.setSelectedIndex(0);
		list.addKeyListener(new _Anon_KeyAdapter_1());
		list.addMouseListener(new _Anon_MouseAdapter_2());
		listPanel.getAccessibleContext().setAccessibleName("Available Types");
		mainPanel.add(listPanel, BorderLayout.CENTER);
		mainPanel.setBorder(new TitledBorder("Select Format"));
		mainPanel.getAccessibleContext().setAccessibleName("Copy Paste Special");
		return mainPanel;
	}

	/* @Override */
	protected void okCallback() {
		close();
		selectedType = listPanel.getSelectedValue();
	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	public ClipboardType getSelectedType() {
		return (ClipboardType) selectedType;
	}


	internal class _Anon_KeyAdapter_1 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent evt) {
				if (evt.getKeyCode() == KeyEvent.VK_ENTER) {
					evt.consume();
					okCallback();
				}
			}
		
	}


	internal class _Anon_MouseAdapter_2 : MouseAdapter
	{

			/* @Override */
			public void mousePressed(MouseEvent evt) {
				if (evt.getButton() == MouseEvent.BUTTON1 && evt.getClickCount() == 2) {
					evt.consume();
					okCallback();
				}
			}
		
	}

